/** Phase 4: Hybrid network-cache collection mode (replaces modal) */
const HYBRID_NETWORK_CACHE_MODE_STORAGE_KEY = "hybrid_network_cache_mode" as const;

// Batch-scoped durable artifact keys: each pilot batch size persists under its own key so a later batch (e.g. Pilot 50)
// can never overwrite or invalidate an earlier batch's milestone artifact (e.g. Pilot 10). The single shared latest alias
// above is still written for backward compatibility and "latest run" diagnostics, but milestone authority reads prefer
// these batch-scoped keys first.
function hybridStartCollectingPilotProductionByBatchStorageKey(batchSize: number): string {
  return `hybridStartCollectingPilotLatestProductionBatch${batchSize}`;
}
function hybridStartCollectingPilotPostVerifyByBatchStorageKey(batchSize: number): string {
  return `hybridStartCollectingPilotLatestPostVerifyBatch${batchSize}`;
}
