function popupRuntimeVersionDiagnostics(): Record<string, unknown> {
  // 22C-14I build identity diagnostics are generated at build time so popup diagnostics can prove Chrome loaded the current dist rather than an older release path.
  return {
    extension_runtime_build_id: EXTENSION_RUNTIME_BUILD_ID,
    popup_runtime_build_id: POPUP_RUNTIME_BUILD_ID,
    runtime_build_id_consistent: EXTENSION_RUNTIME_BUILD_ID === POPUP_RUNTIME_BUILD_ID ? "yes" : "no",
    scanner_runtime_version: SCANNER_RUNTIME_VERSION,
    state_machine_version: STATE_MACHINE_VERSION,
    extension_build_timestamp: EXTENSION_BUILD_TIMESTAMP,
    scan_controller_version: SCAN_CONTROLLER_VERSION,
    scan_post_probe_handoff_version: SCAN_POST_PROBE_HANDOFF_VERSION,
    scan_post_probe_handoff_patch: SCAN_POST_PROBE_HANDOFF_PATCH,
    reset_controller_version: RESET_CONTROLLER_VERSION,
    primary_action_selector_version: PRIMARY_ACTION_SELECTOR_VERSION
  };
}

