type PopupCounterAuthorityPriority = 1 | 2 | 3;
type PopupCounterAuthorityLock = {
  runId: string;
  profileKey: string;
  authority: "scan_job_total_persisted" | "queue_total_persisted" | "post_scan_counter_snapshot" | "queue_preview_length";
  priority: PopupCounterAuthorityPriority;
  total: number;
  stateVersion: string | null;
};

type PopupRenderRunLock = {
  runId: string;
  profileKey: string;
  stateVersion: string | null;
};

let popupCounterAuthorityLock: PopupCounterAuthorityLock | null = null;
let popupRenderRunLock: PopupRenderRunLock | null = null;
let popupLastCoherentAuthorityState: WholeProfileHarvestState | null = null;
let popupPreviousRenderedProfileUrl: string | null = null;
let popupCurrentRenderedProfileUrl: string | null = null;

function notePopupRenderedProfileUrl(activeTabUrl: string | null | undefined): void {
  const active = detectCurrentDouyinProfileIdentity(activeTabUrl, null);
  const canonical = active.canonical_profile_url?.replace(/\/+$/, "") ?? null;
  if (!canonical) return;
  if (popupCurrentRenderedProfileUrl && popupCurrentRenderedProfileUrl !== canonical) {
    popupPreviousRenderedProfileUrl = popupCurrentRenderedProfileUrl;
    void chrome.storage.local.set({ [POPUP_LAST_VISITED_PROFILE_URL_KEY]: popupCurrentRenderedProfileUrl }).catch(() => undefined);
  }
  popupCurrentRenderedProfileUrl = canonical;
}

async function readPopupLastVisitedProfileUrl(): Promise<string | null> {
  const stored = await chrome.storage.local.get(POPUP_LAST_VISITED_PROFILE_URL_KEY).catch(() => ({} as Record<string, unknown>));
  const value = stored[POPUP_LAST_VISITED_PROFILE_URL_KEY];
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function clearedOptimisticScanDebugSummary(summary: Record<string, unknown>): Record<string, unknown> {
  return clearStaleCollectBlockDiagnostics({
    ...summary,
    scan_run_id: null,
    expected_profile_video_count: null,
    scan_progress_expected: null,
    scan_progress_discovered: null,
    scan_progress_pages: null,
    scan_progress_requests: null,
    scan_progress_phase_label: null,
    scan_progress_update_seq: null,
    current_run_found_count: null,
    current_run_new_inserted_total: null,
    current_run_effective_progress_total: null,
    scan_job_total_persisted: null,
    queue_total_persisted: null,
    profile_queue_total_count: null,
    scan_finalization_result: null,
    scan_finalized_at: null,
    profileScanReady: "no"
  });
}

const diagnostics: {
  backendReachable: "yes" | "no" | "unknown";
  activeTabDetected: "yes" | "no" | "unknown";
  supportedDouyinTab: "yes" | "no" | "unknown";
  contentScriptStatus: "ready" | "missing" | "failed";
  detectorStatus: "ready" | "failed";
  detectorError: string | null;
  pageContext: DouyinPageContext | null;
  lastAction: PopupActionName | null;
  lastErrorCategory: PopupErrorCategory | null;
  lastReconnect: "success" | "failed" | "not_needed";
  lastChromeError: string | null;
} = {
  backendReachable: "unknown",
  activeTabDetected: "unknown",
  supportedDouyinTab: "unknown",
  contentScriptStatus: "missing",
  detectorStatus: "failed",
  detectorError: null,
  pageContext: null,
  lastAction: null,
  lastErrorCategory: null,
  lastReconnect: "not_needed",
  lastChromeError: null
};

type WholeProfileHarvestUiPrefs = {
  active_tab: "run" | "results" | "advanced";
  active_panel: "main" | "results" | "advanced";
  quick_start_collapsed: boolean;
  troubleshooting_collapsed: boolean;
  safety_tips_collapsed: boolean;
  settingsExpanded: boolean;
};

function defaultWholeProfileHarvestUiPrefs(): WholeProfileHarvestUiPrefs {
  return {
    active_tab: "run",
    active_panel: "main",
    quick_start_collapsed: false,
    troubleshooting_collapsed: true,
    safety_tips_collapsed: true,
    settingsExpanded: false
  };
}

async function readWholeProfileHarvestUiPrefs(): Promise<WholeProfileHarvestUiPrefs> {
  const stored = await chrome.storage.local.get(WHOLE_PROFILE_UI_PREFS_KEY);
  const value = stored[WHOLE_PROFILE_UI_PREFS_KEY];
  if (!value || typeof value !== "object") return defaultWholeProfileHarvestUiPrefs();
  const candidate = value as Partial<WholeProfileHarvestUiPrefs>;
  return {
    active_tab: candidate.active_tab === "results" || candidate.active_tab === "advanced" ? candidate.active_tab : "run",
    active_panel: candidate.active_panel === "results" || candidate.active_panel === "advanced" ? candidate.active_panel : "main",
    quick_start_collapsed: Boolean(candidate.quick_start_collapsed),
    troubleshooting_collapsed: typeof candidate.troubleshooting_collapsed === "boolean" ? candidate.troubleshooting_collapsed : true,
    safety_tips_collapsed: typeof candidate.safety_tips_collapsed === "boolean" ? candidate.safety_tips_collapsed : true,
    settingsExpanded: typeof candidate.settingsExpanded === "boolean" ? candidate.settingsExpanded : false
  };
}

async function saveWholeProfileHarvestUiPrefs(prefs: WholeProfileHarvestUiPrefs): Promise<void> {
  await chrome.storage.local.set({ [WHOLE_PROFILE_UI_PREFS_KEY]: prefs });
}

async function syncWholeProfileGuidePrefsFromDom(): Promise<void> {
  const prefs = await readWholeProfileHarvestUiPrefs();
  await saveWholeProfileHarvestUiPrefs({
    active_tab: prefs.active_tab,
    active_panel: prefs.active_panel,
    quick_start_collapsed: !wholeProfileQuickStartPanelEl?.open,
    troubleshooting_collapsed: !wholeProfileTroubleshootingPanelEl?.open,
    safety_tips_collapsed: !wholeProfileSafetyTipsPanelEl?.open,
    settingsExpanded: prefs.settingsExpanded
  });
}

async function applyWholeProfileGuidePrefs(): Promise<void> {
  const prefs = await readWholeProfileHarvestUiPrefs();
  applyWholeProfileActiveTab(prefs.active_tab);
  applyScannerSettingsExpanded(false);
  if (wholeProfileQuickStartPanelEl) wholeProfileQuickStartPanelEl.open = !prefs.quick_start_collapsed;
  if (wholeProfileTroubleshootingPanelEl) wholeProfileTroubleshootingPanelEl.open = !prefs.troubleshooting_collapsed;
  if (wholeProfileSafetyTipsPanelEl) wholeProfileSafetyTipsPanelEl.open = !prefs.safety_tips_collapsed;
}

function applyWholeProfileActiveTab(tab: WholeProfileHarvestUiPrefs["active_tab"]): void {
  const entries: Array<{ tab: WholeProfileHarvestUiPrefs["active_tab"]; button: HTMLButtonElement | null; panel: HTMLElement | null }> = [
    { tab: "run", button: wholeProfileTabRunButton, panel: wholeProfileTabRunPanelEl },
    { tab: "results", button: wholeProfileTabResultsButton, panel: wholeProfileTabResultsPanelEl },
    { tab: "advanced", button: wholeProfileTabAdvancedButton, panel: wholeProfileTabAdvancedPanelEl }
  ];
  for (const entry of entries) {
    const active = entry.tab === tab;
    entry.button?.classList.toggle("active", active);
    entry.button?.setAttribute("aria-selected", active ? "true" : "false");
    if (active) entry.panel?.removeAttribute("hidden");
    else entry.panel?.setAttribute("hidden", "true");
  }
}

async function setWholeProfileActiveTab(tab: WholeProfileHarvestUiPrefs["active_tab"]): Promise<void> {
  applyWholeProfileActiveTab(tab);
  const prefs = await readWholeProfileHarvestUiPrefs();
  await saveWholeProfileHarvestUiPrefs({ ...prefs, active_tab: tab, active_panel: prefs.active_panel });
}

