function friendlyWholeProfileErrorMessage(message: string): string {
  if (message.includes("payload_guard_failed") || message.includes("payload_contains_disallowed_field_local")) {
    return "Data check failed. Some unsafe or missing fields were found before saving.";
  }
  if (message.includes("backend_secret_guard_rejected")) {
    return "Save was blocked by backend safety checks.";
  }
  if (message.includes("modal_navigation_timeout")) {
    return "Could not open the video modal in time. Try reconnecting the Douyin tab or using a smaller batch.";
  }
  if (message.includes("captcha_detected")) {
    return "Douyin security check detected. Solve it manually in the Douyin tab, then click Resume.";
  }
  if (message.includes("profile_grid_not_ready")) {
    return "Could not find the profile video grid. Refresh the profile page and scan again.";
  }
  if (message.includes("capture_session_create_failed")) {
    return "Could not create a Save Session.";
  }
  return message;
}

function successWholeProfileMessage(state: WholeProfileHarvestState): string {
  if (state.harvest.backend.batch_flush.status === "completed") return "Batch saved. Open Capture Inbox to review.";
  if (state.harvest.backend.one_item_flush.status === "succeeded") return "1 video saved to Capture Inbox.";
  if (state.harvest.results.some((result) => result.status === "extracted")) return "Metrics extracted. Ready to save.";
  if (state.dry_run.status === "success" || state.dry_run.status === "completed_with_warnings") return `Test passed. ${state.dry_run.pass} videos read successfully.`;
  if (state.verify.status === "success") return `Profile scanned. ${state.verify.verified_target_count || state.profile_scan.accepted_target_count} videos found.`;
  return `${state.phase} complete.`;
}

async function applyHybridEstimatedViewsCollectBetaFlag(): Promise<void> {
  const stored = await chrome.storage.local.get(HYBRID_ESTIMATED_VIEWS_COLLECT_BETA_STORAGE_KEY);
  if (hybridEstimatedViewsCollectBetaEnabledInput) hybridEstimatedViewsCollectBetaEnabledInput.checked = stored[HYBRID_ESTIMATED_VIEWS_COLLECT_BETA_STORAGE_KEY] === true;
}

// Rehydrate the pilot and queue-completion flag checkboxes from chrome.storage.local on popup open. Without this, the flags
// are persisted on change but their checkboxes default to unchecked after every popup reopen, so the enabled-readers (which
// trust the live checkbox state when the control exists) report false even though the operator previously enabled them. This
// matches the existing beta-flag rehydrate and keeps the flags operator-default-false only on genuinely fresh storage.
async function applyHybridPilotAndQueueCompletionFlags(): Promise<void> {
  const pilotStored = await chrome.storage.local.get(HYBRID_ESTIMATED_VIEWS_START_COLLECTING_PILOT_STORAGE_KEY);
  const queue10Stored = await chrome.storage.local.get(HYBRID_START_COLLECTING_PILOT_QUEUE_COMPLETION_STORAGE_KEY);
  const queue50Stored = await chrome.storage.local.get(HYBRID_START_COLLECTING_PILOT_50_QUEUE_COMPLETION_STORAGE_KEY);
  const fullQueueStored = await chrome.storage.local.get(FULL_QUEUE_COMPLETION_FEATURE_FLAG_STORAGE_KEY);
  const hybridNetworkCacheModeStored = await chrome.storage.local.get(HYBRID_NETWORK_CACHE_MODE_STORAGE_KEY);
  if (hybridEstimatedViewsStartCollectingPilotEnabledInput) hybridEstimatedViewsStartCollectingPilotEnabledInput.checked = pilotStored[HYBRID_ESTIMATED_VIEWS_START_COLLECTING_PILOT_STORAGE_KEY] === true;
  if (hybridStartCollectingPilotQueueCompletionEnabledInput) hybridStartCollectingPilotQueueCompletionEnabledInput.checked = queue10Stored[HYBRID_START_COLLECTING_PILOT_QUEUE_COMPLETION_STORAGE_KEY] === true;
  if (hybridStartCollectingPilot50QueueCompletionEnabledInput) hybridStartCollectingPilot50QueueCompletionEnabledInput.checked = queue50Stored[HYBRID_START_COLLECTING_PILOT_50_QUEUE_COMPLETION_STORAGE_KEY] === true;
  if (fullQueueCompletionEnabledInput) fullQueueCompletionEnabledInput.checked = fullQueueStored[FULL_QUEUE_COMPLETION_FEATURE_FLAG_STORAGE_KEY] === true;
  if (hybridNetworkCacheModeEnabledInput) hybridNetworkCacheModeEnabledInput.checked = hybridNetworkCacheModeStored[HYBRID_NETWORK_CACHE_MODE_STORAGE_KEY] === true;
}

async function saveHybridEstimatedViewsCollectBetaFlag(): Promise<void> {
  await chrome.storage.local.set({ [HYBRID_ESTIMATED_VIEWS_COLLECT_BETA_STORAGE_KEY]: hybridEstimatedViewsCollectBetaEnabledInput?.checked === true });
  await renderHybridCollectBetaPrerequisitesPreview();
}

