async function saveHybridNetworkCacheModeFlag(): Promise<void> {
  const enabled = hybridNetworkCacheModeEnabledInput?.checked === true;
  await chrome.storage.local.set({ [HYBRID_NETWORK_CACHE_MODE_STORAGE_KEY]: enabled });
  // Mirror into harvest diagnostics so readiness routes Scan → Start Collecting
  // (skip Calibrate 4 Points) without waiting for a collect run.
  try {
    const now = new Date().toISOString();
    const state = await readWholeProfileHarvestState(chrome.storage.local, now);
    await writeWholeProfileHarvestState(chrome.storage.local, applyHybridNetworkCacheModeFlagToState(state, enabled));
  } catch {
    // non-fatal — read path still injects the flag on next render
  }
  await renderWholeProfileHarvestProductState();
}

