function applyWholeProfileHarvestFeatureMap(): void {
  document.body.dataset.phase18aProduct = "whole_profile_harvest";
  for (const [feature, enabled] of Object.entries(WHOLE_PROFILE_HARVEST_FEATURES)) {
    document.body.dataset[`feature${feature[0]?.toUpperCase() ?? ""}${feature.slice(1)}`] = String(enabled);
  }
}

