const GUARDED_HYBRID_COLLECT_BETA_FLUSH_PATH = "canonical-whole-profile-harvest-one-item" as const;
const GUARDED_HYBRID_COLLECT_BETA_HEADERS = { "X-Reup-Douyin-Flush-Path": GUARDED_HYBRID_COLLECT_BETA_FLUSH_PATH } as const;
const GUARDED_HYBRID_COLLECT_BETA_ALLOWED_BODY_KEYS = new Set(["schema_version", "capture_session_id", "run_id", "profile_url", "target_aweme_id", "source_video_external_id", "started_at", "page", "capture_context", "items", "progress", "commit_policy"]);
