async function runGuardedHybridCollectBetaPostVerifyFromPopup(): Promise<void> {
  const summary = await buildGuardedHybridCollectBetaPostVerifySummary();
  if (guardedHybridCollectBetaPostVerifySummaryPreviewEl) guardedHybridCollectBetaPostVerifySummaryPreviewEl.textContent = JSON.stringify(summary, null, 2);
  const decision = summary.decision as Record<string, unknown>;
  setStatus(decision.post_verify_verdict === "beta_post_verify_passed" ? `Guarded hybrid collect beta post-verify passed; next recommendation: ${String(decision.next_step_recommendation)}.` : `Guarded hybrid collect beta post-verify did not pass: ${String(decision.post_verify_verdict)}.`, decision.post_verify_verdict === "beta_post_verify_passed" ? "good" : "error");
}

// Verify-before-write: pre-check whether every target aweme_id is ALREADY in the backend before issuing the write. If
// every target id is present, the action short-circuits the write to a synthesized idempotent_success — but only because
// an authenticated existence read confirmed the records exist, not because the backend self-reported idempotent. If any
// target id is missing, the real write proceeds. If the existence check itself errors (auth/network/5xx), the write
// status emits `idempotent_check_inconclusive` so the caller retries instead of advancing on phantom data.
async function guardedHybridCollectBetaVerifyBeforeWriteConfirmedCount(payloadPreview: Record<string, unknown> | null): Promise<{ attempted: boolean; confirmed_count: number; queried_aweme_id_count: number; confirms_all: boolean; error: string | null }> {
  const items = Array.isArray(payloadPreview?.items) ? (payloadPreview!.items as Record<string, unknown>[]) : [];
  const writtenAwemeIds = guardedHybridUniqueStrings(items.flatMap((item) => [item?.aweme_id, item?.source_video_external_id]));
  if (writtenAwemeIds.length === 0) return { attempted: false, confirmed_count: 0, queried_aweme_id_count: 0, confirms_all: false, error: "no_written_aweme_ids_in_payload" };
  const captureSessionId = typeof payloadPreview?.capture_session_id === "string" ? (payloadPreview!.capture_session_id as string) : null;
  try {
    const response = await backendJson<Record<string, unknown>>("POST", "/douyin-extension/capture-inbox/items/verify", { aweme_ids: writtenAwemeIds, source_video_external_ids: writtenAwemeIds, capture_session_id: captureSessionId, limit: writtenAwemeIds.length }, { requestStage: "backend_request" });
    const lookupItems = Array.isArray(response.items) ? response.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
    const confirmedById = guardedHybridItemsByAwemeId(lookupItems);
    const confirmedCount = writtenAwemeIds.filter((id) => confirmedById.has(id)).length;
    return { attempted: true, confirmed_count: confirmedCount, queried_aweme_id_count: writtenAwemeIds.length, confirms_all: confirmedCount >= writtenAwemeIds.length, error: null };
  } catch (error) {
    return { attempted: true, confirmed_count: 0, queried_aweme_id_count: writtenAwemeIds.length, confirms_all: false, error: error instanceof Error ? error.message : String(error) };
  }
}

// Verify-after-write: independently confirm the written aweme_ids actually exist in the backend BEFORE the write status can
// claim idempotent_success. The backend `/full-modal-harvest` response is self-reported; trusting its matched/unchanged
// counts let a write that persisted nothing be normalized to idempotent_success (false-idempotent-skip), which beta
// post-verify then exposed as all_backend_items_not_found. This read-only verify queries the same endpoint/scope post-verify
// uses, so a real record is confirmed by the same authority that later reads it.
async function guardedHybridCollectBetaVerifyAfterWriteConfirmedCount(payloadPreview: Record<string, unknown> | null, backendResult: Record<string, unknown>): Promise<{ attempted: boolean; confirmed_count: number; queried_aweme_id_count: number; error: string | null }> {
  const items = Array.isArray(payloadPreview?.items) ? (payloadPreview!.items as Record<string, unknown>[]) : [];
  const writtenAwemeIds = guardedHybridUniqueStrings(items.flatMap((item) => [item?.aweme_id, item?.source_video_external_id]));
  if (writtenAwemeIds.length === 0) return { attempted: false, confirmed_count: 0, queried_aweme_id_count: 0, error: "no_written_aweme_ids_in_payload" };
  const captureSessionId = typeof backendResult.capture_session_id === "string" ? backendResult.capture_session_id : typeof payloadPreview?.capture_session_id === "string" ? (payloadPreview!.capture_session_id as string) : null;
  try {
    const response = await backendJson<Record<string, unknown>>("POST", "/douyin-extension/capture-inbox/items/verify", { aweme_ids: writtenAwemeIds, source_video_external_ids: writtenAwemeIds, capture_session_id: captureSessionId, limit: writtenAwemeIds.length }, { requestStage: "backend_request" });
    const lookupItems = Array.isArray(response.items) ? response.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
    const confirmedById = guardedHybridItemsByAwemeId(lookupItems);
    const confirmedCount = writtenAwemeIds.filter((id) => confirmedById.has(id)).length;
    return { attempted: true, confirmed_count: confirmedCount, queried_aweme_id_count: writtenAwemeIds.length, error: null };
  } catch (error) {
    return { attempted: true, confirmed_count: 0, queried_aweme_id_count: writtenAwemeIds.length, error: error instanceof Error ? error.message : String(error) };
  }
}

async function runGuardedHybridCollectBetaFromPopup(batchSize: 3 | 5): Promise<void> {
  const flagEnabled = await hybridEstimatedViewsCollectBetaEnabled();
  const previewSummary = await buildGuardedHybridCollectBetaSummary(batchSize, flagEnabled);
  const blockers = ((previewSummary.guards as Record<string, unknown>).blockers as string[] | undefined) ?? [];
  if (blockers.length > 0) {
    if (guardedHybridCollectBetaSummaryPreviewEl) guardedHybridCollectBetaSummaryPreviewEl.textContent = JSON.stringify(previewSummary, null, 2);
    await renderHybridCollectBetaPrerequisitesPreview();
    setStatus(`Guarded hybrid collect beta blocked: ${blockers.join(", ")}.`, "error");
    return;
  }
  const payloadSection = previewSummary.payload as Record<string, unknown>;
  const payloadSchemaValidation = (payloadSection.payload_schema_validation as Record<string, unknown> | undefined) ?? {};
  if (payloadSchemaValidation.backend_call_allowed !== "yes") {
    if (guardedHybridCollectBetaSummaryPreviewEl) guardedHybridCollectBetaSummaryPreviewEl.textContent = JSON.stringify(previewSummary, null, 2);
    await renderHybridCollectBetaPrerequisitesPreview();
    setStatus(`Guarded hybrid collect beta blocked by production payload schema: ${String(payloadSchemaValidation.blocker ?? "schema_validation_failed")}.`, "error");
    return;
  }
  const payloadPreview = (payloadSection.production_request_preview as Record<string, unknown> | undefined) ?? null;
  // Pre-write existence check: only short-circuit to idempotent_success when an authenticated read confirms every target
  // aweme_id is already in the backend. If the check itself errors, the status helper emits idempotent_check_inconclusive
  // so the caller retries instead of declaring success on phantom data. Otherwise the real write proceeds normally.
  const verifyBeforeWrite = await guardedHybridCollectBetaVerifyBeforeWriteConfirmedCount(payloadPreview);
  let backendResult: Record<string, unknown>;
  try {
    backendResult = await backendJson<Record<string, unknown>>("POST", GUARDED_HYBRID_COLLECT_BETA_PRODUCTION_ENDPOINT, payloadPreview, { requestStage: "full_modal_harvest", headers: { ...GUARDED_HYBRID_COLLECT_BETA_HEADERS } });
  } catch (error) {
    backendResult = { ok: false, backend_call_attempted: "yes", endpoint_path: GUARDED_HYBRID_COLLECT_BETA_PRODUCTION_ENDPOINT, error: error instanceof Error ? error.message : String(error), error_class: "network_or_local_guard", retryable: false };
  }
  // Independently confirm the written records exist before the write status is allowed to claim idempotent_success.
  const verifyAfterWrite = await guardedHybridCollectBetaVerifyAfterWriteConfirmedCount(payloadPreview, backendResult);
  backendResult = { ...backendResult, verify_before_write_attempted: verifyBeforeWrite.attempted, verify_before_write_confirmed_count: verifyBeforeWrite.confirmed_count, verify_before_write_queried_count: verifyBeforeWrite.queried_aweme_id_count, verify_before_write_confirms_all: verifyBeforeWrite.confirms_all, verify_before_write_error: verifyBeforeWrite.error, verify_after_write_attempted: verifyAfterWrite.attempted, verify_after_write_confirmed_count: verifyAfterWrite.confirmed_count, verify_after_write_queried_count: verifyAfterWrite.queried_aweme_id_count, verify_after_write_error: verifyAfterWrite.error };
  const summary = await buildGuardedHybridCollectBetaSummary(batchSize, flagEnabled, backendResult);
  if (((summary.decision as Record<string, unknown>).safe_for_post_verify === true)) await persistHybridCollectBetaProductionSourceFromSummary(summary);
  if (guardedHybridCollectBetaSummaryPreviewEl) guardedHybridCollectBetaSummaryPreviewEl.textContent = JSON.stringify(summary, null, 2);
  await renderHybridCollectBetaPrerequisitesPreview();
  setStatus(((summary.decision as Record<string, unknown>).safe_for_post_verify === true) ? `Guarded hybrid collect beta succeeded for the controlled ${batchSize}-item batch and is safe for post-verify.` : "Guarded hybrid collect beta backend write failed or is blocked; no local queue completion was applied.", ((summary.decision as Record<string, unknown>).safe_for_post_verify === true) ? "good" : "error");
}


type GuardedHybridStartCollectingPilotBatchSize = 5 | 10 | 50;

function guardedHybridPilotSourceBatchSize(source: HybridCollectBetaProductionSource | null): GuardedHybridStartCollectingPilotBatchSize | 0 {
  const sourceRecord = source as (HybridCollectBetaProductionSource & { pilot_batch_size?: number; requested_batch_size?: number; actual_batch_size?: number }) | null;
  const value = sourceRecord?.pilot_batch_size ?? sourceRecord?.actual_batch_size ?? sourceRecord?.requested_batch_size ?? source?.beta_batch_size ?? 0;
  return value === 50 ? 50 : value === 10 ? 10 : value === 5 ? 5 : 0;
}

async function guardedHybridStartCollectingPilot5PostVerifyPassed(): Promise<boolean> {
  const source = await readGuardedHybridStartCollectingPilotLatestProductionSource();
  if (guardedHybridPilotSourceBatchSize(source) !== 5) return false;
  const summary = await buildGuardedHybridStartCollectingPilotPostVerifySummary();
  const decision = summary.decision as Record<string, unknown>;
  const run = summary.run as Record<string, unknown> | undefined;
  return decision.post_verify_verdict === "pilot_post_verify_passed" && Number(run?.pilot_batch_size ?? run?.actual_batch_size ?? 0) === 5;
}

type GuardedHybridPilotProgressionPrerequisite = {
  progression_prerequisite_checked: true;
  prerequisite_path_selected: "beta_5_post_verify" | "legacy_pilot_5_post_verify" | "pilot_10_post_verify_milestone" | "pilot_10_plus_queue_completion_10_post_verify" | "pilot_50_milestone_authority_supersedes_prerequisites" | "none";
  legacy_pilot_5_post_verify_available: boolean;
  legacy_pilot_5_post_verify_passed: boolean;
  pilot_10_post_verify_available: boolean;
  pilot_10_post_verify_passed: boolean;
  queue_completion_pilot_10_post_verify_available: boolean;
  queue_completion_pilot_10_post_verify_passed: boolean;
  previous_pilot_requirement_satisfied: boolean;
  previous_pilot_requirement_reason: string;
  blockers: string[];
};

type GuardedHybridPilot50ProgressionPrerequisite = GuardedHybridPilotProgressionPrerequisite & {
  prerequisite_path_selected: "legacy_pilot_5_post_verify" | "pilot_10_plus_queue_completion_10_post_verify" | "pilot_50_milestone_authority_supersedes_prerequisites" | "none";
};

function guardedHybridPostVerifySummaryPassedForBatch(summary: Record<string, unknown> | null, batchSize: GuardedHybridStartCollectingPilotBatchSize): boolean {
  const decision = (summary?.decision as Record<string, unknown> | undefined) ?? {};
  const run = (summary?.run as Record<string, unknown> | undefined) ?? {};
  return decision.post_verify_verdict === "pilot_post_verify_passed" && Number(run.pilot_batch_size ?? run.actual_batch_size ?? 0) === batchSize;
}

function guardedHybridQueueCompletionPilot10PostVerifyPassed(summary: Record<string, unknown> | null): boolean {
  const decision = (summary?.decision as Record<string, unknown> | undefined) ?? {};
  const queueVerification = (summary?.queue_verification as Record<string, unknown> | undefined) ?? {};
  const safety = (summary?.safety as Record<string, unknown> | undefined) ?? {};
  return decision.post_verify_verdict === "queue_completion_pilot_post_verify_passed"
    && decision.safe_for_next_phase === true
    && Number(queueVerification.complete_now_count ?? 0) === 10
    && queueVerification.match_strategy === "exact_aweme_id_only"
    && safety.backend_write_attempted === "no"
    && safety.collect_job_mutated === "no"
    && Number(safety.non_verified_queue_items_completed_count ?? 0) === 0;
}

async function readGuardedHybridQueueCompletionPilot10PostVerifySummary(): Promise<Record<string, unknown> | null> {
  return buildGuardedHybridStartCollectingQueueCompletionPilotPostVerifySummary();
}

async function evaluateGuardedPilotProgressionPrerequisites(batchSize: GuardedHybridStartCollectingPilotBatchSize, beta5PostVerifyPassed = false): Promise<GuardedHybridPilotProgressionPrerequisite> {
  const legacyPilot5PostVerifyPassed = await guardedHybridStartCollectingPilot5PostVerifyPassed();
  if (batchSize === 10) {
    const pathSatisfied = beta5PostVerifyPassed || legacyPilot5PostVerifyPassed;
    const blockers = [pathSatisfied ? null : "latest_guarded_hybrid_collect_beta_5_post_verify_pass_missing"].filter((value): value is string => Boolean(value));
    return {
      progression_prerequisite_checked: true,
      prerequisite_path_selected: beta5PostVerifyPassed ? "beta_5_post_verify" : legacyPilot5PostVerifyPassed ? "legacy_pilot_5_post_verify" : "none",
      legacy_pilot_5_post_verify_available: legacyPilot5PostVerifyPassed,
      legacy_pilot_5_post_verify_passed: legacyPilot5PostVerifyPassed,
      pilot_10_post_verify_available: false,
      pilot_10_post_verify_passed: false,
      queue_completion_pilot_10_post_verify_available: false,
      queue_completion_pilot_10_post_verify_passed: false,
      previous_pilot_requirement_satisfied: pathSatisfied,
      previous_pilot_requirement_reason: beta5PostVerifyPassed ? "beta_5_post_verify_passed" : legacyPilot5PostVerifyPassed ? "legacy_pilot_5_post_verify_passed_backward_compatible" : "latest_guarded_hybrid_collect_beta_5_post_verify_pass_missing",
      blockers
    };
  }
  const pilotStored = await chrome.storage.local.get(HYBRID_START_COLLECTING_PILOT_LATEST_POST_VERIFY_STORAGE_KEY);
  const pilotPostVerify = (pilotStored[HYBRID_START_COLLECTING_PILOT_LATEST_POST_VERIFY_STORAGE_KEY] as Record<string, unknown> | undefined) ?? null;
  const queueCompletionPostVerify = await readGuardedHybridQueueCompletionPilot10PostVerifySummary();
  const pilot10PostVerifyPassed = guardedHybridPostVerifySummaryPassedForBatch(pilotPostVerify, 10);
  const queueCompletionPilot10PostVerifyPassed = guardedHybridQueueCompletionPilot10PostVerifyPassed(queueCompletionPostVerify);
  const pathB = pilot10PostVerifyPassed && queueCompletionPilot10PostVerifyPassed;
  const pathA = legacyPilot5PostVerifyPassed;
  const blockers = batchSize === 50 ? [
    pilot10PostVerifyPassed || pathA ? null : "latest_guarded_hybrid_start_collecting_pilot_10_post_verify_pass_missing",
    queueCompletionPilot10PostVerifyPassed || pathA ? null : "latest_queue_completion_pilot_10_post_verify_pass_missing",
    pathA || pathB ? null : "previous_pilot_requirement_not_satisfied"
  ].filter((value): value is string => Boolean(value)) : [];
  return {
    progression_prerequisite_checked: true,
    prerequisite_path_selected: pathB ? "pilot_10_plus_queue_completion_10_post_verify" : pathA ? "legacy_pilot_5_post_verify" : "none",
    legacy_pilot_5_post_verify_available: pathA,
    legacy_pilot_5_post_verify_passed: legacyPilot5PostVerifyPassed,
    pilot_10_post_verify_available: pilotPostVerify != null,
    pilot_10_post_verify_passed: pilot10PostVerifyPassed,
    queue_completion_pilot_10_post_verify_available: queueCompletionPostVerify != null,
    queue_completion_pilot_10_post_verify_passed: queueCompletionPilot10PostVerifyPassed,
    previous_pilot_requirement_satisfied: batchSize === 50 ? pathA || pathB : true,
    previous_pilot_requirement_reason: pathB ? "pilot_10_plus_queue_completion_10_post_verify_passed" : pathA ? "legacy_pilot_5_post_verify_passed" : batchSize === 50 ? "missing_pilot_10_plus_queue_completion_10_or_legacy_pilot_5_post_verify" : "no_previous_pilot_required",
    blockers
  };
}

async function evaluateGuardedHybridPilot50ProgressionPrerequisite(): Promise<GuardedHybridPilot50ProgressionPrerequisite> {
  return await evaluateGuardedPilotProgressionPrerequisites(50) as GuardedHybridPilot50ProgressionPrerequisite;
}

