  const schemaBlocker = typeof payloadSchemaValidation.blocker === "string" ? payloadSchemaValidation.blocker : null;
  const allBlockers = [...blockers, metricFidelityBlocker, schemaBlocker].filter((value): value is string => Boolean(value));
  const backendStatus = backendResult ? guardedHybridBackendWriteStatus(backendResult, rows.length) : null;
  const backendWrite = backendResult ?? { backend_call_attempted: allBlockers.length === 0 ? "pending" : "no", endpoint_path: GUARDED_HYBRID_COLLECT_BETA_PRODUCTION_ENDPOINT, ok: null, accepted_count: 0, rejected_count: 0, blocker: allBlockers[0] ?? null };
  const verdict = backendStatus?.effectiveStatus === "idempotent_success" ? "pilot_collect_idempotent_success" : backendStatus?.normalizedOk === true ? "pilot_collect_succeeded" : backendResult ? "pilot_collect_backend_failed" : allBlockers.length > 0 ? "pilot_blocked_preconditions" : "ready_for_guarded_start_collecting_pilot_write";
