// FULL_QUEUE_COMPLETION executor (FIX 2): the real, operator-triggered, feature-flagged, chunked, resumable, idempotent
// executor. It does NOT collect missing videos. It only MARKS already-backend-backed queue items as
// status="backend_verified", capture_status="complete" using exact_aweme_id_only matching against the LIVE backend.
// Items without a live backend record stay pending. Re-running never double-marks. Persists progress under
// FULL_QUEUE_COMPLETION_PROGRESS_STORAGE_KEY so it resumes after popup close, tab close, token expiry, or restart.
type FullQueueCompletionProgressRecord = {
  schema_version: "full_queue_completion_progress.v1";
  status: "running" | "completed" | "paused_auth_required" | "paused_error" | "idle";
  capture_session_id: string | null;
  started_at: string;
  last_resumed_at: string;
  last_updated_at: string;
  total_chunk_count: number;
  processed_chunk_count: number;
  processed_aweme_id_count: number;
  backend_backed_count: number;
  marked_complete_count: number;
  already_complete_count: number;
  not_backend_backed_pending_count: number;
  not_backend_backed_pending_aweme_ids_sample: string[];
  last_error: string | null;
  auth_required: boolean;
};

async function readFullQueueCompletionProgress(): Promise<FullQueueCompletionProgressRecord | null> {
  const stored = await chrome.storage.local.get(FULL_QUEUE_COMPLETION_PROGRESS_STORAGE_KEY);
  const record = stored[FULL_QUEUE_COMPLETION_PROGRESS_STORAGE_KEY];
  return record && typeof record === "object" && (record as Record<string, unknown>).schema_version === "full_queue_completion_progress.v1"
    ? (record as FullQueueCompletionProgressRecord)
    : null;
}

async function writeFullQueueCompletionProgress(record: FullQueueCompletionProgressRecord): Promise<void> {
  await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_PROGRESS_STORAGE_KEY]: record });
}

async function runFullQueueCompletion(): Promise<Record<string, unknown>> {
  const startedAt = new Date().toISOString();
  // Hard precondition: feature flag must be explicitly enabled by the operator.
  const flagEnabled = await fullQueueCompletionFeatureFlagEnabled();
  if (!flagEnabled) {
    const summary = {
      summary_title: "FULL_QUEUE_COMPLETION_LATEST",
      generated_at: startedAt,
      verdict: "blocked_feature_flag_disabled",
      blockers: ["full_queue_completion_feature_flag_disabled"],
      marked_complete_count: 0,
      already_complete_count: 0,
      not_backend_backed_pending_count: 0,
      backend_backed_count: 0,
      queue_total: 0,
      auth_required: false,
      safety: { scan_profile_changed: "no", normal_start_collecting_replaced: "no", queue_completion_match_strategy: "exact_aweme_id_only", estimated_views_copied_to_view_count: "no", backend_write_attempted: "no" }
    };
    await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY]: summary });
    return summary;
  }
  // Read the local queue and resolve a live capture_session_id for scoped verify.
  const stateBefore = await readWholeProfileHarvestState(chrome.storage.local, startedAt);
  const runnerLock = deriveAuthoritativeRunnerLock(stateBefore);
  if (stateBefore.collect_job?.state === "running" || runnerLock.active || stateBefore.workflow.action_lock === "scan_profile") {
    const summary = {
      summary_title: "FULL_QUEUE_COMPLETION_LATEST",
      generated_at: startedAt,
      verdict: "blocked_active_collect_or_scan_lock",
      blockers: [stateBefore.collect_job?.state === "running" || runnerLock.active ? "active_collect_job_running" : "scan_action_lock_active"],
      marked_complete_count: 0,
      already_complete_count: 0,
      not_backend_backed_pending_count: 0,
      backend_backed_count: 0,
      queue_total: 0,
      auth_required: false,
      safety: { scan_profile_changed: "no", normal_start_collecting_replaced: "no", queue_completion_match_strategy: "exact_aweme_id_only", estimated_views_copied_to_view_count: "no", backend_write_attempted: "no" }
    };
    await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY]: summary });
    return summary;
  }
  // One-time mechanism-validation precondition (Pilot 50 proved the mechanism once).
  const postVerifySource = await readGuardedHybridStartCollectingPilot50PostVerifySource();
  const pilot50PostVerifyPassedOnce = postVerifySource.blockers.length === 0 && postVerifySource.verifiedAwemeIds.length === 50;
  if (!pilot50PostVerifyPassedOnce) {
    const summary = {
      summary_title: "FULL_QUEUE_COMPLETION_LATEST",
      generated_at: startedAt,
      verdict: "blocked_mechanism_validation_not_passed",
      blockers: ["pilot_50_post_verify_mechanism_validation_not_passed_once"],
      marked_complete_count: 0,
      already_complete_count: 0,
      not_backend_backed_pending_count: 0,
      backend_backed_count: 0,
      queue_total: 0,
      auth_required: false,
      safety: { scan_profile_changed: "no", normal_start_collecting_replaced: "no", queue_completion_match_strategy: "exact_aweme_id_only", estimated_views_copied_to_view_count: "no", backend_write_attempted: "no" }
    };
    await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY]: summary });
    return summary;
  }
  const captureSessionId = typeof stateBefore.capture_session_id === "string" && stateBefore.capture_session_id.trim()
    ? stateBefore.capture_session_id.trim()
    : typeof stateBefore.harvest?.backend?.capture_session?.session_id === "string" && stateBefore.harvest.backend.capture_session.session_id.trim()
      ? stateBefore.harvest.backend.capture_session.session_id.trim()
      : null;
  // Resume policy: keep prior progress record only as a diagnostic; the executor is fully idempotent because it only
  // marks items where !guardedHybridQueueCompletionItemIsComplete(item), and re-running over already-complete items
  // is a no-op. We rebuild progress from a fresh state read every run so backend changes are picked up.
  const priorProgress = await readFullQueueCompletionProgress();
  const queue: WholeProfileHarvestQueueItem[] = Array.isArray(stateBefore.harvest?.queue) ? stateBefore.harvest.queue : [];
  const allQueueAwemeIds = guardedHybridUniqueStrings(queue.map((item) => item.aweme_id));
  const queueTotal = allQueueAwemeIds.length;
  const totalChunkCount = queueTotal === 0 ? 0 : Math.ceil(queueTotal / FULL_QUEUE_COMPLETION_CHUNK_SIZE);
  // Initial progress record under the running status. Rewritten after each chunk for resumability.
  const initialProgress: FullQueueCompletionProgressRecord = {
    schema_version: "full_queue_completion_progress.v1",
    status: "running",
    capture_session_id: captureSessionId,
    started_at: priorProgress?.started_at ?? startedAt,
    last_resumed_at: startedAt,
    last_updated_at: startedAt,
    total_chunk_count: totalChunkCount,
    processed_chunk_count: 0,
    processed_aweme_id_count: 0,
    backend_backed_count: 0,
    marked_complete_count: 0,
    already_complete_count: queue.filter(guardedHybridQueueCompletionItemIsComplete).length,
    not_backend_backed_pending_count: 0,
    not_backend_backed_pending_aweme_ids_sample: [],
    last_error: null,
    auth_required: false
  };
  await writeFullQueueCompletionProgress(initialProgress);
  const backendBackedSet = new Set<string>();
  const allErrors: string[] = [];
  let authRequired = false;
  let chunkIndex = 0;
  let processedAwemeIdCount = 0;
  for (let offset = 0; offset < allQueueAwemeIds.length; offset += FULL_QUEUE_COMPLETION_CHUNK_SIZE) {
    const chunk = allQueueAwemeIds.slice(offset, offset + FULL_QUEUE_COMPLETION_CHUNK_SIZE);
    chunkIndex += 1;
    processedAwemeIdCount += chunk.length;
    const chunkResult = await liveBackendVerifyAwemeIds(chunk, captureSessionId);
    if (chunkResult.auth_required) {
      authRequired = true;
      allErrors.push(...chunkResult.errors);
      break;
    }
    for (const id of chunkResult.found_aweme_ids) backendBackedSet.add(id);
    if (chunkResult.errors.length > 0) allErrors.push(...chunkResult.errors);
    // Persist mid-run progress so a tab close or restart can be observed by the operator.
    await writeFullQueueCompletionProgress({
      ...initialProgress,
      processed_chunk_count: chunkIndex,
      processed_aweme_id_count: processedAwemeIdCount,
      backend_backed_count: backendBackedSet.size,
      last_updated_at: new Date().toISOString()
    });
  }
  // If auth expired, stop safely without recording false "not found". Re-running after re-auth resumes naturally.
  if (authRequired) {
    const summary = {
      summary_title: "FULL_QUEUE_COMPLETION_LATEST",
      generated_at: new Date().toISOString(),
      verdict: "paused_auth_required",
      blockers: ["backend_auth_required_resume_after_login"],
      marked_complete_count: 0,
      already_complete_count: queue.filter(guardedHybridQueueCompletionItemIsComplete).length,
      not_backend_backed_pending_count: 0,
      backend_backed_count: backendBackedSet.size,
      queue_total: queueTotal,
      auth_required: true,
      processed_chunk_count: chunkIndex,
      total_chunk_count: totalChunkCount,
      capture_session_id: captureSessionId,
      live_verify_errors: compactStringArray(allErrors, 8),
      safety: { scan_profile_changed: "no", normal_start_collecting_replaced: "no", queue_completion_match_strategy: "exact_aweme_id_only", estimated_views_copied_to_view_count: "no", backend_write_attempted: "no" }
    };
    await writeFullQueueCompletionProgress({
      ...initialProgress,
      processed_chunk_count: chunkIndex,
      processed_aweme_id_count: processedAwemeIdCount,
      backend_backed_count: backendBackedSet.size,
      status: "paused_auth_required",
      auth_required: true,
      last_error: allErrors[0] ?? "auth_required",
      last_updated_at: summary.generated_at
    });
    await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY]: summary });
    return summary;
  }
  // Apply the marking pass: idempotent, exact_aweme_id_only, only items already pending and backend-backed.
  const completedAt = new Date().toISOString();
  let markedCompleteCount = 0;
  const notBackendBackedPendingAwemeIds: string[] = [];
  const nextQueue = queue.map((item) => {
    if (guardedHybridQueueCompletionItemIsComplete(item)) return item;
    if (!backendBackedSet.has(item.aweme_id)) {
      if (notBackendBackedPendingAwemeIds.length < FULL_QUEUE_COMPLETION_NOT_BACKED_PROGRESS_CAP) {
        notBackendBackedPendingAwemeIds.push(item.aweme_id);
      }
      return item;
    }
    markedCompleteCount += 1;
    return {
      ...item,
      status: "backend_verified" as const,
      capture_status: "complete" as const,
      last_attempt_at: completedAt,
      saved_at: item.saved_at ?? completedAt,
      profile_card_evidence: {
        ...item.profile_card_evidence,
        full_queue_completion_marked: true,
        full_queue_completion_capture_session_id: captureSessionId,
        completed_at: completedAt
      }
    };
  });
  const stateAfter = markedCompleteCount === 0
    ? stateBefore
    : await writeWholeProfileHarvestState(chrome.storage.local, {
        ...stateBefore,
        harvest: {
          ...stateBefore.harvest,
          queue: nextQueue,
          pending: guardedHybridQueueCompletionPendingCount(nextQueue),
          updated_at: completedAt
        },
        updated_at: completedAt
      });
  if (markedCompleteCount > 0) {
    latestWholeProfileHarvestState = stateAfter;
    renderWholeProfileHarvestProductStateFromState(stateAfter, "none");
  }
  const finalSummary = {
    summary_title: "FULL_QUEUE_COMPLETION_LATEST",
    generated_at: completedAt,
    verdict: "completed",
    blockers: [],
    marked_complete_count: markedCompleteCount,
    already_complete_count: queue.filter(guardedHybridQueueCompletionItemIsComplete).length,
    not_backend_backed_pending_count: notBackendBackedPendingAwemeIds.length,
    not_backend_backed_pending_aweme_ids_sample: notBackendBackedPendingAwemeIds.slice(0, FULL_QUEUE_COMPLETION_NOT_BACKED_SAMPLE_CAP),
    backend_backed_count: backendBackedSet.size,
    queue_total: queueTotal,
    auth_required: false,
    processed_chunk_count: chunkIndex,
    total_chunk_count: totalChunkCount,
    capture_session_id: captureSessionId,
    live_verify_errors: compactStringArray(allErrors, 8),
    match_strategy: "exact_aweme_id_only",
    safety: {
      scan_profile_changed: "no",
      normal_start_collecting_replaced: "no",
      full_queue_completion_enabled: true,
      queue_completion_match_strategy: "exact_aweme_id_only",
      estimated_views_formula: "tiered_like_multiplier_v1",
      estimated_views_copied_to_view_count: "no",
      backend_write_attempted: "no",
      idempotent_re_run_safe: "yes"
    }
  };
  await writeFullQueueCompletionProgress({
    ...initialProgress,
    processed_chunk_count: chunkIndex,
    processed_aweme_id_count: processedAwemeIdCount,
    backend_backed_count: backendBackedSet.size,
    marked_complete_count: markedCompleteCount,
    already_complete_count: finalSummary.already_complete_count,
    not_backend_backed_pending_count: notBackendBackedPendingAwemeIds.length,
    not_backend_backed_pending_aweme_ids_sample: notBackendBackedPendingAwemeIds.slice(0, FULL_QUEUE_COMPLETION_NOT_BACKED_SAMPLE_CAP),
    status: "completed",
    auth_required: false,
    last_error: allErrors[0] ?? null,
    last_updated_at: completedAt
  });
  await chrome.storage.local.set({ [FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY]: finalSummary });
  return finalSummary;
}

async function runFullQueueCompletionFromPopup(): Promise<void> {
  const summary = await runFullQueueCompletion();
  if (fullQueueCompletionLatestPreviewEl) fullQueueCompletionLatestPreviewEl.textContent = JSON.stringify(summary, null, 2);
  const verdict = String((summary as Record<string, unknown>).verdict ?? "unknown");
  const markedCount = Number((summary as Record<string, unknown>).marked_complete_count ?? 0);
  setStatus(
    verdict === "completed"
      ? `Full queue completion marked ${markedCount} backend-backed item${markedCount === 1 ? "" : "s"} complete.`
      : verdict === "paused_auth_required"
        ? "Full queue completion paused: backend auth required. Log in and re-run."
        : `Full queue completion blocked: ${verdict}.`,
    verdict === "completed" ? "good" : "error"
  );
}

async function copyFullQueueCompletionLatestFromPopup(): Promise<void> {
  const stored = await chrome.storage.local.get(FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY);
  const latest = stored[FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY] ?? null;
  const json = fullQueueCompletionLatestPreviewEl?.textContent?.trim() || JSON.stringify(latest ?? { summary_title: "FULL_QUEUE_COMPLETION_LATEST", verdict: "not_run_yet" }, null, 2);
  await navigator.clipboard?.writeText(json);
  setStatus("Copied full queue completion latest JSON.", "good");
}

async function resetFullQueueCompletionProgressFromPopup(): Promise<void> {
  await chrome.storage.local.remove(FULL_QUEUE_COMPLETION_PROGRESS_STORAGE_KEY);
  await chrome.storage.local.remove(FULL_QUEUE_COMPLETION_LATEST_STORAGE_KEY);
  if (fullQueueCompletionLatestPreviewEl) fullQueueCompletionLatestPreviewEl.textContent = "FULL_QUEUE_COMPLETION_LATEST not run yet.";
  setStatus("Full queue completion progress reset. Local queue completions are preserved.", "good");
}

// Read-only beta backend evidence dump. This performs NO writes: it reads the persisted beta production source artifact,
// computes the exact id set beta production used as its write target and the exact id set + key/namespace beta post-verify
// uses to look up backend items, then issues read-only lookups to /douyin-extension/capture-inbox/items/verify so we can
// resolve the contradiction (idempotent_success vs zero items found) with real data instead of guessing.
//
// Two read-only lookups are issued against the SAME endpoint post-verify uses:
//   1. scoped: { aweme_ids, capture_session_id } exactly as buildGuardedHybridCollectBetaPostVerifySummary does.
//   2. unscoped: { aweme_ids } only (no capture_session_id), to detect whether records exist but are filtered out by a
//      capture_session_id/run-scope mismatch (lookup-mismatch) versus genuinely absent (false-idempotent-skip).
// If unscoped finds the records but scoped does not, the verdict is lookup_scope_mismatch. If neither finds them, the
// verdict is false_idempotent_skip_no_backend_record. This is the single piece of evidence that distinguishes the two.
async function buildGuardedHybridCollectBetaBackendEvidenceDump(): Promise<Record<string, unknown>> {
  const source = await readHybridCollectBetaLatestProductionSource();
  const generatedAt = new Date().toISOString();
  if (!source) {
    return {
      summary_title: "GUARDED_HYBRID_COLLECT_BETA_BACKEND_EVIDENCE_DUMP",
      read_only: true,
      storage_mutation: "none",
      generated_at: generatedAt,
      source_available: "no",
      verdict: "no_beta_production_source_artifact",
      note: "no persisted beta production source artifact found at the shared latest production key"
    };
  }
  const requiredBetaBatchSize = source.beta_batch_size === 10 ? 10 : source.beta_batch_size === 5 ? 5 : source.beta_batch_size === 3 ? 3 : 0;
  // Production write target id set: exactly what hybridCollectBetaProductionSourceFromSummary persisted as accepted/flushed.
  const productionAcceptedAwemeIds = guardedHybridUniqueStrings([...(source.accepted_aweme_ids ?? []), ...(source.flushed_aweme_ids ?? [])]);
  const productionSourceVideoExternalIds = guardedHybridUniqueStrings([...(source.source_video_external_ids ?? [])]);
  // Post-verify lookup id set: the exact derivation used by buildGuardedHybridCollectBetaPostVerifySummary.
  const postVerifyAcceptedAwemeIds = guardedHybridUniqueStrings([...(source.accepted_aweme_ids ?? []), ...(source.flushed_aweme_ids ?? [])]).slice(0, requiredBetaBatchSize || undefined);
  const postVerifySourceVideoExternalIds = guardedHybridUniqueStrings([...(source.source_video_external_ids ?? []), ...(source.flushed_aweme_ids ?? []), ...postVerifyAcceptedAwemeIds]);
  const idSetsIdentical = productionAcceptedAwemeIds.length === postVerifyAcceptedAwemeIds.length && productionAcceptedAwemeIds.every((id) => postVerifyAcceptedAwemeIds.includes(id));
  const verifyEndpoint = "/douyin-extension/capture-inbox/items/verify";
  const productionWriteEndpoint = GUARDED_HYBRID_COLLECT_BETA_PRODUCTION_ENDPOINT;
  const captureSessionId = source.capture_session_id;
  const errors: string[] = [];
  let scopedItems: Record<string, unknown>[] = [];
  let unscopedItems: Record<string, unknown>[] = [];
  let scopedAttempted = false;
  let unscopedAttempted = false;
  if (postVerifyAcceptedAwemeIds.length > 0 || postVerifySourceVideoExternalIds.length > 0) {
    scopedAttempted = true;
    try {
      const scopedResponse = await backendJson<Record<string, unknown>>("POST", verifyEndpoint, { aweme_ids: postVerifyAcceptedAwemeIds, source_video_external_ids: postVerifySourceVideoExternalIds, capture_session_id: captureSessionId, limit: Math.max(postVerifyAcceptedAwemeIds.length, postVerifySourceVideoExternalIds.length, 1) }, { requestStage: "backend_request" });
      scopedItems = Array.isArray(scopedResponse.items) ? scopedResponse.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
    } catch (error) {
      errors.push(`scoped_lookup_error:${error instanceof Error ? error.message : String(error)}`);
    }
    unscopedAttempted = true;
    try {
      const unscopedResponse = await backendJson<Record<string, unknown>>("POST", verifyEndpoint, { aweme_ids: postVerifyAcceptedAwemeIds, source_video_external_ids: postVerifySourceVideoExternalIds, limit: Math.max(postVerifyAcceptedAwemeIds.length, postVerifySourceVideoExternalIds.length, 1) }, { requestStage: "backend_request" });
      unscopedItems = Array.isArray(unscopedResponse.items) ? unscopedResponse.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
    } catch (error) {
      errors.push(`unscoped_lookup_error:${error instanceof Error ? error.message : String(error)}`);
    }
  }
  const scopedByAwemeId = guardedHybridItemsByAwemeId(scopedItems);
  const unscopedByAwemeId = guardedHybridItemsByAwemeId(unscopedItems);
  const fieldKeys = ["title", "caption", "thumbnail_url", "cover_url", "like_count", "share_count", "estimated_views", "estimated_views_formula", "view_count", "metadata_status", "capture_session_id"];
  const perId = postVerifyAcceptedAwemeIds.map((awemeId) => {
    const scopedItem = scopedByAwemeId.get(awemeId) ?? null;
    const unscopedItem = unscopedByAwemeId.get(awemeId) ?? null;
    const presentFields = (item: Record<string, unknown> | null): string[] => item ? fieldKeys.filter((key) => item[key] != null) : [];
    return {
      aweme_id: awemeId,
      found_scoped_by_capture_session_id: scopedItem != null,
      found_unscoped_aweme_id_only: unscopedItem != null,
      scoped_present_fields: presentFields(scopedItem),
      unscoped_present_fields: presentFields(unscopedItem),
      backend_capture_session_id: unscopedItem != null ? (unscopedItem.capture_session_id ?? null) : null
    };
  });
  const scopedFoundCount = perId.filter((row) => row.found_scoped_by_capture_session_id).length;
  const unscopedFoundCount = perId.filter((row) => row.found_unscoped_aweme_id_only).length;
  const required = requiredBetaBatchSize || postVerifyAcceptedAwemeIds.length;
  // Data-driven verdict. The two lookups discriminate the two hypotheses precisely.
  let verdict: string;
  if (errors.length > 0 && scopedItems.length === 0 && unscopedItems.length === 0) {
    verdict = "inconclusive_backend_lookup_error";
  } else if (unscopedFoundCount === 0) {
    // Records do not exist under any scope -> the write never actually persisted them despite idempotent_success.
    verdict = "false_idempotent_skip_no_backend_record";
  } else if (unscopedFoundCount > 0 && scopedFoundCount < unscopedFoundCount) {
    // Records exist but the capture_session_id scope filters them out -> post-verify queries the wrong run-scope.
    verdict = "lookup_scope_mismatch_capture_session_id";
  } else if (scopedFoundCount >= required && required > 0) {
    verdict = "backend_records_present_post_verify_should_pass";
  } else {
    verdict = "inconclusive_review_per_id_evidence";
  }
  const backendDeclaredIdempotent = (() => {
    const bw = source.backend_write_summary ?? {};
    const status = typeof bw.beta_write_effective_status === "string" ? bw.beta_write_effective_status : null;
    return status === "idempotent_success" || Number(bw.idempotent_unchanged_count ?? 0) > 0;
  })();
  return {
    summary_title: "GUARDED_HYBRID_COLLECT_BETA_BACKEND_EVIDENCE_DUMP",
    read_only: true,
    storage_mutation: "none",
    pipeline_stages_rerun: "none",
    generated_at: generatedAt,
    source_available: "yes",
    beta_batch_size: source.beta_batch_size,
    source_beta_run_id: source.source_beta_run_id ?? null,
    backend_write_declared_idempotent_success: backendDeclaredIdempotent,
    write_target: {
      endpoint: productionWriteEndpoint,
      capture_session_id_sent_in_write_payload: null,
      capture_session_id_resolved_into_source_from_response: captureSessionId,
      capture_session_resolved_by: source.capture_session_resolved_by ?? null,
      accepted_aweme_id_count: productionAcceptedAwemeIds.length,
      accepted_aweme_ids: productionAcceptedAwemeIds,
      source_video_external_ids: productionSourceVideoExternalIds
    },
    post_verify_lookup: {
      endpoint: verifyEndpoint,
      lookup_key: "aweme_ids",
      capture_session_id_filter: captureSessionId,
      accepted_aweme_id_count: postVerifyAcceptedAwemeIds.length,
      accepted_aweme_ids: postVerifyAcceptedAwemeIds,
      source_video_external_ids: postVerifySourceVideoExternalIds
    },
    id_set_comparison: {
      production_vs_post_verify_identical: idSetsIdentical,
      production_only_ids: productionAcceptedAwemeIds.filter((id) => !postVerifyAcceptedAwemeIds.includes(id)),
      post_verify_only_ids: postVerifyAcceptedAwemeIds.filter((id) => !productionAcceptedAwemeIds.includes(id)),
      lookup_endpoint_differs_from_write_endpoint: String(verifyEndpoint) !== String(productionWriteEndpoint)
    },
    backend_read: {
      scoped_lookup_attempted: scopedAttempted,
      unscoped_lookup_attempted: unscopedAttempted,
      scoped_found_count: scopedFoundCount,
      unscoped_found_count: unscopedFoundCount,
      required,
      per_id: perId,
      errors
    },
    verdict,
    verdict_explanation:
      verdict === "false_idempotent_skip_no_backend_record"
        ? "no backend record exists for the accepted aweme_ids under any scope (scoped or unscoped), so the write was skipped as idempotent_success without ever persisting the records (false-idempotent-skip)"
        : verdict === "lookup_scope_mismatch_capture_session_id"
          ? "records exist when queried by aweme_id alone but are filtered out when scoped by source.capture_session_id, so post-verify queries the wrong run-scope (lookup-mismatch)"
          : verdict === "backend_records_present_post_verify_should_pass"
            ? "scoped lookup found the required records; post-verify should pass for this source"
            : verdict === "inconclusive_backend_lookup_error"
              ? "both lookups errored; cannot determine record existence"
              : "review the per_id evidence; mixed results"
  };
}

async function exportGuardedHybridCollectBetaBackendEvidenceDumpFromPopup(): Promise<void> {
  const dump = await buildGuardedHybridCollectBetaBackendEvidenceDump();
  if (guardedHybridCollectBetaBackendEvidenceDumpPreviewEl) guardedHybridCollectBetaBackendEvidenceDumpPreviewEl.textContent = JSON.stringify(dump, null, 2);
  setStatus(`Exported beta backend evidence dump. Verdict: ${String(dump.verdict)}.`, dump.verdict === "backend_records_present_post_verify_should_pass" ? "good" : "error");
}

async function copyGuardedHybridCollectBetaBackendEvidenceDumpFromPopup(): Promise<void> {
  const dump = guardedHybridCollectBetaBackendEvidenceDumpPreviewEl?.textContent?.trim() || JSON.stringify(await buildGuardedHybridCollectBetaBackendEvidenceDump(), null, 2);
  await navigator.clipboard.writeText(dump);
  setStatus("Copied beta backend evidence dump to clipboard.", "good");
}

// Read-only Pilot 50 backend evidence dump (same shape as the beta backend evidence dump). This performs NO writes,
// NO pipeline rerun, and NO pilot auto-rerun. It reads the verified Pilot 50 aweme_id set (from the latest passed Pilot 50
// post-verify source artifact / stored aliases) and issues authenticated read-only lookups against the CURRENT backend to
// resolve whether Pilot 50 is actually backend-backed right now or only passing from stored chrome.storage artifacts.
// Two lookups are issued against the same verify endpoint post-verify uses:
//   1. scoped: { aweme_ids, capture_session_id } as the pilot post-verify would scope.
//   2. unscoped: { aweme_ids } only, to detect records that exist but are filtered out by a capture_session_id mismatch.
// Verdict: backend_backed when the scoped lookup finds all required verified ids; artifact_only when the records are not
// present in the current backend (so Pilot 50 passes only from stored artifacts after the backend reset).
async function buildGuardedHybridPilot50BackendEvidenceDump(): Promise<Record<string, unknown>> {
  const generatedAt = new Date().toISOString();
  const postVerifySource = await readGuardedHybridStartCollectingPilot50PostVerifySource();
  const verifiedAwemeIds = guardedHybridUniqueStrings(postVerifySource.verifiedAwemeIds);
  const productionSource = await readGuardedHybridStartCollectingPilotLatestProductionSource();
  const captureSessionId = productionSource?.capture_session_id ?? null;
  const sourceRunId = (productionSource as (HybridCollectBetaProductionSource & { source_pilot_run_id?: string }) | null)?.source_pilot_run_id ?? productionSource?.source_run_id ?? null;
  const pilot50PostVerifyPassedFromArtifacts = postVerifySource.blockers.length === 0 && verifiedAwemeIds.length === 50;
  if (verifiedAwemeIds.length === 0) {
    return {
      summary_title: "GUARDED_HYBRID_PILOT_50_BACKEND_EVIDENCE_DUMP",
      read_only: true,
      storage_mutation: "none",
      pipeline_stages_rerun: "none",
      pilots_auto_rerun: "no",
      generated_at: generatedAt,
      source_available: "no",
      pilot_50_post_verify_passed_from_artifacts: pilot50PostVerifyPassedFromArtifacts,
      pilot_50_post_verify_artifact_blockers: compactStringArray(postVerifySource.blockers, 16),
      verdict: "no_verified_pilot_50_source_artifact",
      verdict_explanation: "no verified Pilot 50 aweme_id set could be resolved from the latest passed Pilot 50 post-verify source artifact, so there is nothing to check against the current backend"
    };
  }
  const required = verifiedAwemeIds.length;
  const verifyEndpoint = "/douyin-extension/capture-inbox/items/verify";
  const errors: string[] = [];
  let scopedItems: Record<string, unknown>[] = [];
  let unscopedItems: Record<string, unknown>[] = [];
  let scopedAttempted = false;
  let unscopedAttempted = false;
  if (captureSessionId) {
    scopedAttempted = true;
    try {
      const scopedResponse = await backendJson<Record<string, unknown>>("POST", verifyEndpoint, { aweme_ids: verifiedAwemeIds, capture_session_id: captureSessionId, limit: Math.max(verifiedAwemeIds.length, 1) }, { requestStage: "backend_request" });
      scopedItems = Array.isArray(scopedResponse.items) ? scopedResponse.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
    } catch (error) {
      errors.push(`scoped_lookup_error:${error instanceof Error ? error.message : String(error)}`);
    }
  }
  unscopedAttempted = true;
  try {
    const unscopedResponse = await backendJson<Record<string, unknown>>("POST", verifyEndpoint, { aweme_ids: verifiedAwemeIds, limit: Math.max(verifiedAwemeIds.length, 1) }, { requestStage: "backend_request" });
    unscopedItems = Array.isArray(unscopedResponse.items) ? unscopedResponse.items.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === "object" && !Array.isArray(item))) : [];
  } catch (error) {
    errors.push(`unscoped_lookup_error:${error instanceof Error ? error.message : String(error)}`);
  }
  const scopedByAwemeId = guardedHybridItemsByAwemeId(scopedItems);
  const unscopedByAwemeId = guardedHybridItemsByAwemeId(unscopedItems);
  const fieldKeys = ["title", "caption", "thumbnail_url", "cover_url", "like_count", "share_count", "estimated_views", "estimated_views_formula", "view_count", "metadata_status", "capture_session_id"];
  const perId = verifiedAwemeIds.map((awemeId) => {
    const scopedItem = scopedByAwemeId.get(awemeId) ?? null;
    const unscopedItem = unscopedByAwemeId.get(awemeId) ?? null;
    const presentFields = (item: Record<string, unknown> | null): string[] => item ? fieldKeys.filter((key) => item[key] != null) : [];
    return {
      aweme_id: awemeId,
      found_scoped_by_capture_session_id: scopedItem != null,
      found_unscoped_aweme_id_only: unscopedItem != null,
      found: scopedItem != null || unscopedItem != null ? "yes" : "no",
      scoped_present_fields: presentFields(scopedItem),
      unscoped_present_fields: presentFields(unscopedItem),
      backend_capture_session_id: unscopedItem != null ? (unscopedItem.capture_session_id ?? null) : null
    };
  });
  const scopedFoundCount = perId.filter((row) => row.found_scoped_by_capture_session_id).length;
  const unscopedFoundCount = perId.filter((row) => row.found_unscoped_aweme_id_only).length;
  const anyFoundCount = perId.filter((row) => row.found === "yes").length;
  // Verdict: backend_backed vs artifact_only.
  let verdict: string;
  if (errors.length > 0 && scopedItems.length === 0 && unscopedItems.length === 0) {
    verdict = "inconclusive_backend_lookup_error";
  } else if (anyFoundCount === 0) {
    verdict = "artifact_only";
  } else if (scopedFoundCount >= required && required > 0) {
    verdict = "backend_backed";
  } else if (unscopedFoundCount >= required && required > 0) {
    verdict = "backend_backed_scope_mismatch";
  } else {
    verdict = "partially_backend_backed";
  }
  return {
    summary_title: "GUARDED_HYBRID_PILOT_50_BACKEND_EVIDENCE_DUMP",
    read_only: true,
    storage_mutation: "none",
    pipeline_stages_rerun: "none",
    pilots_auto_rerun: "no",
    generated_at: generatedAt,
    source_available: "yes",
    pilot_50_post_verify_passed_from_artifacts: pilot50PostVerifyPassedFromArtifacts,
    pilot_50_post_verify_artifact_blockers: compactStringArray(postVerifySource.blockers, 16),
    verified_source: {
      source: "latest_passed_pilot_50_post_verify_artifact",
      source_pilot_run_id: sourceRunId,
      verified_aweme_id_count: verifiedAwemeIds.length,
      verified_aweme_ids: verifiedAwemeIds
    },
    backend_lookup: {
      endpoint: verifyEndpoint,
      lookup_key: "aweme_ids",
      capture_session_id_filter: captureSessionId,
      capture_session_id_available: captureSessionId != null,
      scoped_lookup_attempted: scopedAttempted,
      unscoped_lookup_attempted: unscopedAttempted,
      scoped_found_count: scopedFoundCount,
      unscoped_found_count: unscopedFoundCount,
      any_found_count: anyFoundCount,
      required,
      per_id: perId,
      errors
    },
    safety: {
      backend_write_attempted: "no",
      backend_read_only_verification: "yes",
      pipeline_rerun: "no",
      pilot_auto_rerun: "no",
      full_queue_completion_enabled: false,
      queue_completion_match_strategy: "exact_aweme_id_only",
      estimated_views_copied_to_view_count: "no",
      estimated_views_formula: "tiered_like_multiplier_v1"
    },
    verdict,
    verdict_explanation:
      verdict === "backend_backed"
        ? "the scoped backend lookup found all required verified Pilot 50 aweme_ids in the current backend, so Pilot 50 is backend-backed right now"
        : verdict === "backend_backed_scope_mismatch"
          ? "all required verified Pilot 50 aweme_ids exist in the current backend by aweme_id but not under the stored capture_session_id scope, so Pilot 50 is backend-backed but the stored capture_session_id no longer matches the current backend scope"
          : verdict === "artifact_only"
            ? "none of the verified Pilot 50 aweme_ids were found in the current backend under any scope, so Pilot 50 is passing only from stored chrome.storage artifacts/aliases and is NOT backend-backed after the backend reset"
            : verdict === "partially_backend_backed"
              ? "only some of the verified Pilot 50 aweme_ids were found in the current backend; Pilot 50 is partially backend-backed, review per_id evidence"
              : "both lookups errored; cannot determine current backend record existence"
  };
}

