type GuardedPipelineStorageNamespaceName = "local" | "session" | "sync";
type GuardedPipelineStorageArea = { get(keys: string | string[]): Promise<Record<string, unknown>> };

type GuardedPipelineInventoryCandidate = {
  stage: string;
  key: string;
  namespace: GuardedPipelineStorageNamespaceName;
  role: "actual_writer_and_compact_reader" | "actual_writer" | "compact_reader" | "legacy_or_fallback_probe" | "rebuilt_virtual_post_verify_source";
  durable_latest_alias: boolean;
};

function guardedPipelineStorageInventoryCandidates(namespace: GuardedPipelineStorageNamespaceName): GuardedPipelineInventoryCandidate[] {
  return [
    { stage: "hybrid_only_dry_run_50", key: HYBRID_COLLECT_BETA_LATEST_DRY_RUN_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "backend_shadow_5", key: HYBRID_COLLECT_BETA_LATEST_SHADOW_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "guarded_hybrid_collect_beta_5", key: HYBRID_COLLECT_BETA_LATEST_PRODUCTION_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "guarded_hybrid_collect_beta_5_post_verify", key: HYBRID_COLLECT_BETA_LATEST_PRODUCTION_STORAGE_KEY, namespace, role: "rebuilt_virtual_post_verify_source", durable_latest_alias: false },
    { stage: "guarded_start_collecting_pilot_10", key: HYBRID_START_COLLECTING_PILOT_LATEST_PRODUCTION_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "guarded_start_collecting_pilot_blocked_attempt", key: HYBRID_START_COLLECTING_PILOT_LATEST_BLOCKED_ATTEMPT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "guarded_start_collecting_pilot_10_post_verify", key: HYBRID_START_COLLECTING_PILOT_LATEST_POST_VERIFY_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "hybrid_only_dry_run_50_compact", key: HYBRID_COLLECT_BETA_LATEST_DRY_RUN_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "backend_shadow_5_compact", key: HYBRID_COLLECT_BETA_LATEST_SHADOW_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "guarded_hybrid_collect_beta_5_compact", key: HYBRID_COLLECT_BETA_LATEST_PRODUCTION_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "guarded_start_collecting_pilot_compact", key: HYBRID_START_COLLECTING_PILOT_LATEST_PRODUCTION_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "guarded_start_collecting_pilot_post_verify_compact", key: HYBRID_START_COLLECTING_PILOT_LATEST_POST_VERIFY_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "queue_completion_pilot_10", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_LATEST_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "queue_completion_pilot_10_post_verify", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_LATEST_STORAGE_KEY, namespace, role: "rebuilt_virtual_post_verify_source", durable_latest_alias: false },
    { stage: "queue_completion_pilot_50", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_50_LATEST_STORAGE_KEY, namespace, role: "actual_writer_and_compact_reader", durable_latest_alias: true },
    { stage: "queue_completion_pilot_10_compact", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_LATEST_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "queue_completion_pilot_50_compact", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_50_LATEST_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true },
    { stage: "queue_completion_pilot_50_post_verify", key: HYBRID_START_COLLECTING_QUEUE_COMPLETION_PILOT_50_LATEST_STORAGE_KEY, namespace, role: "rebuilt_virtual_post_verify_source", durable_latest_alias: false },
    { stage: "guarded_pipeline_to_pilot_50_compact", key: GUARDED_PIPELINE_TO_PILOT_50_LATEST_COMPACT_STORAGE_KEY, namespace, role: "actual_writer", durable_latest_alias: true }
  ];
}

function guardedPipelineStorageArea(namespace: GuardedPipelineStorageNamespaceName): GuardedPipelineStorageArea | null {
  const storage = chrome.storage as unknown as Partial<Record<GuardedPipelineStorageNamespaceName, GuardedPipelineStorageArea>>;
  const area = storage[namespace];
  return area && typeof area.get === "function" ? area : null;
}

function guardedPipelineInventoryNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function guardedPipelineInventoryString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null;
}

function guardedPipelineInventoryNestedRecord(value: Record<string, unknown>, key: string): Record<string, unknown> {
  const nested = value[key];
  return nested && typeof nested === "object" && !Array.isArray(nested) ? nested as Record<string, unknown> : {};
}

function guardedPipelineInventoryItemCount(value: Record<string, unknown>): number | null {
  const arrays = ["rows", "accepted_aweme_ids", "verified_aweme_ids", "source_verified_aweme_ids", "artifacts", "run_log"];
  for (const key of arrays) {
    const candidate = value[key];
    if (Array.isArray(candidate)) return candidate.length;
  }
  const numericKeys = ["accepted_count", "completed_sample_size", "actual_shadow_sample_size", "actual_batch_size", "pilot_batch_size", "beta_batch_size", "requested_completion_count", "complete_now_count"];
  for (const key of numericKeys) {
    const numeric = guardedPipelineInventoryNumber(value[key]);
    if (numeric != null) return numeric;
  }
  return null;
}

function guardedPipelineInventoryBlockerCount(value: Record<string, unknown>): number {
  const decision = guardedPipelineInventoryNestedRecord(value, "decision");
  const readiness = guardedPipelineInventoryNestedRecord(value, "queue_completion_readiness");
  return compactStringArray(value.blockers, 100).length + compactStringArray(decision.blockers, 100).length + compactStringArray(readiness.blockers, 100).length;
}

function guardedPipelineStorageInventorySummary(candidate: GuardedPipelineInventoryCandidate, value: unknown, namespaceAvailable: boolean): Record<string, unknown> {
  const exists = value != null;
  const record = exists && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const run = guardedPipelineInventoryNestedRecord(record, "run");
  const decision = guardedPipelineInventoryNestedRecord(record, "decision");
  const backendWrite = guardedPipelineInventoryNestedRecord(record, "backend_write_summary");
  const productionState = guardedPipelineInventoryNestedRecord(record, "production_state");
  return {
    stage: candidate.stage,
    key: candidate.key,
    namespace: candidate.namespace,
    namespace_available: namespaceAvailable,
    role: candidate.role,
    durable_latest_alias: candidate.durable_latest_alias,
    exists,
    top_level_keys: Object.keys(record).sort().slice(0, 80),
    source_run_id: guardedPipelineInventoryString(record.source_run_id) ?? guardedPipelineInventoryString(run.source_run_id) ?? null,
    run_id: guardedPipelineInventoryString(record.run_id) ?? guardedPipelineInventoryString(run.run_id) ?? null,
    source_pilot_run_id: guardedPipelineInventoryString(record.source_pilot_run_id) ?? guardedPipelineInventoryString(run.source_pilot_run_id) ?? null,
    pilot_run_id: guardedPipelineInventoryString(record.pilot_run_id) ?? guardedPipelineInventoryString(run.pilot_run_id) ?? null,
    source_beta_run_id: guardedPipelineInventoryString(record.source_beta_run_id) ?? guardedPipelineInventoryString(run.source_beta_run_id) ?? null,
    beta_batch_size: guardedPipelineInventoryNumber(record.beta_batch_size) ?? guardedPipelineInventoryNumber(run.beta_batch_size),
    pilot_batch_size: guardedPipelineInventoryNumber(record.pilot_batch_size) ?? guardedPipelineInventoryNumber(run.pilot_batch_size),
    actual_batch_size: guardedPipelineInventoryNumber(record.actual_batch_size) ?? guardedPipelineInventoryNumber(run.actual_batch_size),
    completed_sample_size: guardedPipelineInventoryNumber(record.completed_sample_size),
    accepted_count: guardedPipelineInventoryNumber(record.accepted_count),
    rejected_count: guardedPipelineInventoryNumber(record.rejected_count),
    verdict: guardedPipelineInventoryString(record.verdict) ?? guardedPipelineInventoryString(decision.verdict) ?? guardedPipelineInventoryString(decision.post_verify_verdict) ?? guardedPipelineInventoryString(backendWrite.verdict) ?? null,
    status: guardedPipelineInventoryString(record.status) ?? guardedPipelineInventoryString(decision.status) ?? guardedPipelineInventoryString(productionState.status) ?? null,
    item_count: exists ? guardedPipelineInventoryItemCount(record) : null,
    blocker_count: exists ? guardedPipelineInventoryBlockerCount(record) : 0,
    updated_at_present: Boolean(record.updated_at || record.generated_at || run.generated_at || record.completed_at)
  };
}

async function buildGuardedPipelineStorageInventory(): Promise<Record<string, unknown>> {
  const namespaces: GuardedPipelineStorageNamespaceName[] = ["local", "session", "sync"];
  const entries: Record<string, unknown>[] = [];
  for (const namespace of namespaces) {
    const area = guardedPipelineStorageArea(namespace);
    const candidates = guardedPipelineStorageInventoryCandidates(namespace);
    const values = area ? await area.get([...new Set(candidates.map((candidate) => candidate.key))]) : {};
    entries.push(...candidates.map((candidate) => guardedPipelineStorageInventorySummary(candidate, values[candidate.key], area != null)));
  }
  return {
    summary_title: "GUARDED_PIPELINE_STORAGE_INVENTORY",
    generated_at: new Date().toISOString(),
    build: popupRuntimeVersionDiagnostics(),
    read_only: true,
    storage_mutation: "none",
    pipeline_stages_rerun: "none",
    scan_profile_changed: "no",
    normal_start_collecting_changed: "no",
    queue_completion_enabled: "no",
    estimated_views_or_view_count_changed: "no",
    artifact_absence_conclusion_policy: "inventory_only_do_not_infer_from_compact_status",
    compact_export_adjacent_placeholders: "individual summary not-run placeholders are adjacent popup preview text, not proof that individual summary exports ran",
    entries
  };
}

function backendShadowRowEvidenceRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function backendShadowRowEvidenceNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function backendShadowRowEvidenceBoolean(value: unknown): boolean {
  return value === true || value === "yes";
}

function backendShadowRowEvidenceItems(value: unknown): Record<string, unknown>[] {
  const artifact = backendShadowRowEvidenceRecord(value);
  const summary = backendShadowRowEvidenceRecord(artifact.summary);
  const payloadValidation = backendShadowRowEvidenceRecord(summary.payload_validation);
  const payloadPreview = backendShadowRowEvidenceRecord(payloadValidation.payload_preview);
  return Array.isArray(payloadPreview.items) ? payloadPreview.items.map((item) => backendShadowRowEvidenceRecord(item)) : [];
}

function backendShadowProductionWriteAttempted(artifact: Record<string, unknown>, summary: Record<string, unknown>, row: Record<string, unknown>): "yes" | "no" {
  const safety = backendShadowRowEvidenceRecord(summary.safety);
  const backendResult = backendShadowRowEvidenceRecord(summary.backend_result);
  return artifact.production_mutation_detected === true
    || safety.production_mutation_detected === "yes"
    || backendResult.production_mutation_detected === "yes"
    || row.production_backend_write_attempted === true
    || row.production_backend_write_attempted === "yes"
    ? "yes"
    : "no";
}

function backendShadowRowEvidence(row: Record<string, unknown>, index: number, acceptedCount: number, productionBackendWriteAttempted: "yes" | "no"): Record<string, unknown> {
  const rawLikeCount = backendShadowRowEvidenceNumber(row.raw_like_count) ?? backendShadowRowEvidenceNumber(row.like_count);
  const payloadTitle = typeof row.title === "string" ? row.title.trim() : "";
  const payloadTitlePresent = payloadTitle.length > 0;
  const titleIsIdFallback = backendShadowRowEvidenceBoolean(row.title_is_id_fallback);
  const dryRunTitleWasRealText = backendShadowRowEvidenceBoolean(row.dry_run_title_was_real_text ?? row.title_valid_real_text);
  const rowAwemeId = typeof row["aweme_id"] === "string" ? row["aweme_id"] : null;
  const rowSourceVideoExternalId = typeof row["source_video_external_id"] === "string" ? row["source_video_external_id"] : null;
  const payloadTitleEqualsAwemeId = backendShadowRowEvidenceBoolean(row.payload_title_equals_aweme_id) || (payloadTitlePresent && (payloadTitle === rowAwemeId || payloadTitle === rowSourceVideoExternalId));
  const outgoingPayloadTitleIsRealText = backendShadowRowEvidenceBoolean(row.outgoing_payload_title_is_real_text) || (payloadTitlePresent && dryRunTitleWasRealText && !titleIsIdFallback && !payloadTitleEqualsAwemeId);
  const outgoingPayloadRawLikeCountExactNumeric = backendShadowRowEvidenceBoolean(row.outgoing_payload_raw_like_count_exact_numeric ?? row.raw_like_count_exact_numeric) || backendShadowRowEvidenceNumber(row.like_count) != null;
  return {
    payload_title_present: payloadTitlePresent,
    payload_title_length: payloadTitle.length,
    payload_title_source: typeof row.title_source === "string" ? row.title_source : null,
    outgoing_payload_title_is_real_text: outgoingPayloadTitleIsRealText,
    "payload_title_equals_aweme_id": payloadTitleEqualsAwemeId,
    dry_run_title_was_real_text: dryRunTitleWasRealText,
    title_dropped_between_dry_run_and_payload: dryRunTitleWasRealText && !payloadTitlePresent,
    title_is_id_fallback: titleIsIdFallback,
    outgoing_payload_raw_like_count_exact_numeric: outgoingPayloadRawLikeCountExactNumeric,
    raw_like_count: rawLikeCount,
    raw_like_count_source: rawLikeCount == null ? null : "payload.like_count",
    backend_shadow_accepted: index < acceptedCount,
    production_backend_write_attempted: productionBackendWriteAttempted
  };
}

async function buildBackendShadowRowEvidence(): Promise<Record<string, unknown>> {
  const stored = await chrome.storage.local.get(HYBRID_COLLECT_BETA_LATEST_SHADOW_STORAGE_KEY);
  const artifact = backendShadowRowEvidenceRecord(stored[HYBRID_COLLECT_BETA_LATEST_SHADOW_STORAGE_KEY]);
  const summary = backendShadowRowEvidenceRecord(artifact.summary);
  const rows = backendShadowRowEvidenceItems(artifact);
  const accepted_count = backendShadowRowEvidenceNumber(artifact.accepted_count) ?? 0;
  const rejected_count = backendShadowRowEvidenceNumber(artifact.rejected_count) ?? 0;
  const productionBackendWriteAttemptedAny = rows.some((row) => backendShadowProductionWriteAttempted(artifact, summary, row) === "yes") || backendShadowProductionWriteAttempted(artifact, summary, {}) === "yes";
  const rowEvidence = rows.map((row, index) => backendShadowRowEvidence(row, index, accepted_count, backendShadowProductionWriteAttempted(artifact, summary, row)));
  return {
    summary_title: "BACKEND_SHADOW_ROW_EVIDENCE",
    generated_at: new Date().toISOString(),
    build: popupRuntimeVersionDiagnostics(),
    read_only: true,
    storage_namespace: "chrome.storage.local",
    source_storage_key: HYBRID_COLLECT_BETA_LATEST_SHADOW_STORAGE_KEY,
    storage_mutation: "none",
    backend_mutation: "none",
    production_beta_run: "no",
    pipeline_stages_rerun: "none",
    sanitized_output: "compact_sample_no_raw_ids_no_thumbnails_no_backend_bodies",
    sample_policy: "first_5_rows_only",
    accepted_count,
    rejected_count,
    title_payload_real_text_count: rowEvidence.filter((row) => row.outgoing_payload_title_is_real_text === true).length,
    title_payload_id_fallback_count: rowEvidence.filter((row) => row.title_is_id_fallback === true).length,
    raw_like_payload_exact_numeric_count: rowEvidence.filter((row) => row.outgoing_payload_raw_like_count_exact_numeric === true).length,
    rounded_like_payload_rejected_count: rowEvidence.filter((row) => row.rounded_like_display_rejected_for_raw === true).length,
    production_backend_write_attempted_any: productionBackendWriteAttemptedAny ? "yes" : "no",
    sample_size: Math.min(rows.length, 5),
    rows_sample: rowEvidence.slice(0, 5)
  };
}

